#include <bits/stdc++.h>
using namespace std;

// Direction vectors: up, down, left, right
const int dx[4] = {-1, 1, 0, 0};
const int dy[4] = {0, 0, -1, 1};

struct State {
    int x, y;      // head position
    int mask;      // bitmask of eaten foods (foods 1..9)
    int tail[5][2]; // positions of the 5 body segments (a,b,c,d,e) relative to head? 
    // Actually we need to store the whole body shape to check collisions.
    // Simpler: store the whole body as a deque of positions (head first, then segments).
    // But for BFS state we need to encode it efficiently.
};

// For BFS we can store the whole body as a string of positions or use hashing.
// Since grid is small (max 10x10?), we can store as vector<pair<int,int>>.
// But number of states can be large. Let's use a set for visited.

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> grid;
    string line;
    while (getline(cin, line)) {
        if (line.empty()) break;
        grid.push_back(line);
    }

    int H = grid.size();
    int W = grid[0].size();

    // Locate initial positions
    int sx, sy;
    vector<pair<int,int>> body(5); // a,b,c,d,e in order from head to tail
    // Actually "S" is head, then 'a','b','c','d','e' are body segments.
    // We'll store body[0] = head, body[1] = 'a', ..., body[5] = 'e'
    // But we need to find them.
    vector<pair<int,int>> initBody(6); // index 0=head, 1='a',2='b',3='c',4='d',5='e'
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            char c = grid[i][j];
            if (c == 'S') {
                initBody[0] = {i, j};
            } else if (c == 'a') {
                initBody[1] = {i, j};
            } else if (c == 'b') {
                initBody[2] = {i, j};
            } else if (c == 'c') {
                initBody[3] = {i, j};
            } else if (c == 'd') {
                initBody[4] = {i, j};
            } else if (c == 'e') {
                initBody[5] = {i, j};
            }
        }
    }

    // Determine which foods exist (1..9)
    int foodMaskTarget = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                int idx = grid[i][j] - '1';
                foodMaskTarget |= (1 << idx);
            }
        }
    }

    // BFS: state = (head x, head y, body positions as vector, eaten mask)
    // To save memory, we can encode body as a string of positions (compact).
    // But since max grid 10x10, we can store as vector of 6 pairs.
    // Use a hash set for visited: we can convert state to a string key.

    auto makeKey = [&](int hx, int hy, const vector<pair<int,int>>& bodyPos, int mask) -> string {
        string key;
        key += to_string(hx) + "," + to_string(hy) + ",";
        for (auto& p : bodyPos) {
            key += to_string(p.first) + "," + to_string(p.second) + ",";
        }
        key += to_string(mask);
        return key;
    };

    queue<tuple<int,int,vector<pair<int,int>>,int>> q; // hx, hy, body, mask
    unordered_set<string> visited;

    vector<pair<int,int>> initBodyVec = initBody; // index 0=head, 1..5=body
    q.push({initBody[0].first, initBody[0].second, initBodyVec, 0});
    visited.insert(makeKey(initBody[0].first, initBody[0].second, initBodyVec, 0));

    int steps = 0;
    while (!q.empty()) {
        int sz = q.size();
        while (sz--) {
            auto [hx, hy, bodyVec, mask] = q.front(); q.pop();

            // Check if all food eaten
            if (mask == foodMaskTarget) {
                cout << steps << "\n";
                return 0;
            }

            // Try 4 directions
            for (int d = 0; d < 4; d++) {
                int nhx = hx + dx[d];
                int nhy = hy + dy[d];

                // Check bounds
                if (nhx < 0 || nhx >= H || nhy < 0 || nhy >= W) continue;
                // Check obstacle
                if (grid[nhx][nhy] == '#') continue;

                // Check if new head position collides with body (except the last segment which will move away)
                bool collision = false;
                for (int i = 1; i < 6; i++) { // i=1..5 are body segments
                    if (bodyVec[i].first == nhx && bodyVec[i].second == nhy) {
                        collision = true;
                        break;
                    }
                }
                if (collision) continue;

                // Move: new head becomes (nhx,nhy), body shifts: old head becomes new body[1], old body[1] becomes body[2], etc.
                vector<pair<int,int>> newBody(6);
                newBody[0] = {nhx, nhy};
                for (int i = 1; i < 6; i++) {
                    newBody[i] = bodyVec[i-1];
                }

                // Check if new head is on a food that hasn't been eaten yet
                int newMask = mask;
                char cell = grid[nhx][nhy];
                if (cell >= '1' && cell <= '9') {
                    int foodIdx = cell - '1';
                    if (!(newMask & (1 << foodIdx))) {
                        newMask |= (1 << foodIdx);
                        // After eating, the food cell becomes empty? The problem says head overlaps with food when eating.
                        // It doesn't say food disappears, but typically it does. However, it says "eat the food", so we mark it eaten.
                        // The grid itself doesn't change, but we track via mask.
                    }
                }

                string key = makeKey(nhx, nhy, newBody, newMask);
                if (!visited.count(key)) {
                    visited.insert(key);
                    q.push({nhx, nhy, newBody, newMask});
                }
            }
        }
        steps++;
    }

    cout << -1 << "\n";
    return 0;
}

