int main() {
    // read grid
    int R, C;
    // assume input format
    vector<string> grid;
    string line;
    while (getline(cin, line)) {
        if (!line.empty()) grid.push_back(line);
    }
    R = grid.size(); C = grid[0].size();

    array<int,6> init_pos;
    // find S, a, b, c, d, e
    char order[] = {'S','a','b','c','d','e'};
    for (int i = 0; i < 6; i++) {
        for (int r = 0; r < R; r++)
            for (int c = 0; c < C; c++)
                if (grid[r][c] == order[i]) init_pos[i] = r*C+c;
    }

    // find max food
    int maxFood = 0;
    for (auto& row : grid) for (char ch : row) if (ch>='1'&&ch<='9') maxFood = max(maxFood, ch-'0');

    // BFS
    // state: 6 positions + next food (0 means need food 1)
    map<pair<array<int,6>,int>, int> dist;
    queue<pair<array<int,6>,int>> q;
    auto startState = make_pair(init_pos, 0);
    dist[startState] = 0;
    q.push(startState);
    int dx[]={-1,1,0,0}, dy[]={0,0,-1,1};

    while (!q.empty()) {
        auto [pos, nf] = q.front(); q.pop();
        int d = dist[{pos,nf}];
        if (nf == maxFood) { cout << d << endl; return 0; }

        int hr = pos[0]/C, hc = pos[0]%C;
        for (int dir = 0; dir < 4; dir++) {
            int nr = hr+dx[dir], nc = hc+dy[dir];
            if (nr<0||nr>=R||nc<0||nc>=C) continue;
            if (grid[nr][nc]=='#') continue;
            int np = nr*C+nc;
            // check not in body (pos[0..4] become new body[1..5])
            bool ok = true;
            for (int i = 0; i < 5; i++) if (np == pos[i]) { ok=false; break; }
            if (!ok) continue;
            array<int,6> npos = {np, pos[0], pos[1], pos[2], pos[3], pos[4]};
            int nnf = nf;
            char cell = grid[nr][nc];
            if (cell>='1'&&cell<='9' && cell-'0' == nf+1) nnf = nf+1;
            auto ns = make_pair(npos, nnf);
            if (!dist.count(ns)) {
                dist[ns] = d+1;
                q.push(ns);
            }
        }
    }
    cout << -1 << endl;
}

#include <bits/stdc++.h>
using namespace std;

struct State {
    array<int, 6> p; // 0=head, 1..5 body
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> g(H);
    for (int i = 0; i < H; i++) cin >> g[i];

    const int MAXF = 9;
    vector<pair<int,int>> food(MAXF + 1, {-1, -1});
    array<pair<int,int>, 6> initPos;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            char c = g[i][j];
            if (c == 'S') initPos[0] = {i, j};
            else if ('a' <= c && c <= 'e') initPos[c - 'a' + 1] = {i, j};
            else if ('1' <= c && c <= '9') food[c - '0'] = {i, j};
        }
    }

    int F = 0;
    for (int i = 1; i <= MAXF; i++) {
        if (food[i].first != -1) F = i;
        else break;
    }

    auto id = [&](int r, int c) { return r * W + c; };
    auto inside = [&](int r, int c) { return 0 <= r && r < H && 0 <= c && c < W; };

    State init;
    for (int i = 0; i < 6; i++) init.p[i] = id(initPos[i].first, initPos[i].second);

    auto encode = [&](const State& s) -> unsigned long long {
        // each position fits in 6 bits if <= 63? not guaranteed.
        // Use mixed radix with base H*W, works if packed into 64-bit for typical constraints.
        // Safer: still okay for H,W<=15 (classic problem). But let's avoid assumptions:
        // we won't use this.
        return 0;
    };

    struct KeyHash {
        size_t operator()(const array<int,6>& a) const {
            size_t h = 0;
            for (int x : a) h = h * 1315423911u + x + 0x9e3779b97f4a7c15ULL;
            return h;
        }
    };

    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    auto bfs = [&](State start, pair<int,int> target, State &finish) -> int {
        queue<State> q;
        unordered_map<array<int,6>, int, KeyHash> dist;

        q.push(start);
        dist[start.p] = 0;

        int targetId = id(target.first, target.second);

        while (!q.empty()) {
            State cur = q.front(); q.pop();
            int d = dist[cur.p];

            if (cur.p[0] == targetId) {
                finish = cur;
                return d;
            }

            int hr = cur.p[0] / W, hc = cur.p[0] % W;

            for (int mv = 0; mv < 4; mv++) {
                int nr = hr + dr[mv], nc = hc + dc[mv];
                if (!inside(nr, nc)) continue;
                if (g[nr][nc] == '#') continue;
                int nid = id(nr, nc);

                bool bad = false;
                for (int i = 0; i < 5; i++) { // cannot move into current head/body except tail vacates
                    if (cur.p[i] == nid) {
                        bad = true;
                        break;
                    }
                }
                if (bad) continue;

                State nxt;
                nxt.p[0] = nid;
                for (int i = 1; i < 6; i++) nxt.p[i] = cur.p[i-1];

                if (!dist.count(nxt.p)) {
                    dist[nxt.p] = d + 1;
                    q.push(nxt);
                }
            }
        }
        return -1;
    };

    int ans = 0;
    State cur = init, nxt;

    for (int k = 1; k <= F; k++) {
        int d = bfs(cur, food[k], nxt);
        if (d == -1) {
            cout << -1 << '\n';
            return 0;
        }
        ans += d;
        cur = nxt;
    }

    cout << ans << '\n';
    return 0;
}

from collections import deque

def solve():
    import sys
    grid = []
    for line in sys.stdin:
        line = line.rstrip('\n')
        if line:
            grid.append(line)

    R = len(grid)
    C = len(grid[0]) if R > 0 else 0

    positions = {}
    foods = {}

    for r in range(R):
        for c in range(C):
            ch = grid[r][c]
            if ch == 'S':
                positions['S'] = (r, c)
            elif ch in 'abcde':
                positions[ch] = (r, c)
            elif ch in '123456789':
                foods[ch] = (r, c)

    order = sorted(foods.keys())
    num_foods = len(order)

    init = (positions['S'], positions['a'], positions['b'], positions['c'], positions['d'], positions['e'], 0)

    dist = {init: 0}
    q = deque([init])

    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    while q:
        state = q.popleft()
        segs = state[:6]
        fi = state[6]
        d = dist[state]

        if fi == num_foods:
            print(d)
            return

        hr, hc = segs[0]
        for dr, dc in dirs:
            nr, nc = hr+dr, hc+dc
            if nr < 0 or nr >= R or nc < 0 or nc >= C:
                continue
            cell = grid[nr][nc]
            if cell == '#':
                continue
            new_head = (nr, nc)
            new_body = segs[:5]  # old head becomes a, old a becomes b, etc.
            if new_head in new_body:
                continue
            new_fi = fi
            if fi < num_foods and new_head == foods[order[fi]]:
                new_fi = fi + 1
            new_state = (new_head,) + new_body + (new_fi,)
            if new_state not in dist:
                dist[new_state] = d + 1
                q.append(new_state)

    print(-1)

solve()

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_H 50
#define MAX_W 50
#define MAX_FOOD 9

typedef struct {
    int x, y;
} Point;

typedef struct {
    Point body[6]; // head + 5 segments, body[0] is head
} State;

int H, W;
char grid[MAX_H][MAX_W+1];
int food_count;
Point food_pos[MAX_FOOD+1]; // 1-indexed
int food_order[MAX_FOOD+1]; // order of food to eat, 0 means none
int target_order; // how many food items we need to eat

// BFS state: we encode the state as a combination of head position and body positions
// We'll do a BFS with visited array for each food step
// Since the body is always connected and moves like a snake, we can represent
// the state by the positions of the 6 segments.
// We'll use a 6D visited? That's too big. Instead, we can do BFS for each food target.
// For each food target, we BFS from current head+body to the food position,
// treating the body as obstacles that move.

// But the body moves, so we need to track the full state. However, the grid is small (max 50x50=2500),
// and the body is only 6 cells. The number of states is bounded by (2500 choose 6) which is huge.
// We need a smarter approach.

// Observation: The caterpillar moves like a snake. The head moves, and each segment follows.
// So the state is determined by the head position and the directions of the body segments.
// Since there are only 5 body segments, the number of possible body shapes is limited.
// We can do BFS with a visited array of size H*W * (something for body shape).
// Actually, we can encode the body as a sequence of relative positions from the head.
// Since the body is always connected and cannot overlap, the number of possible configurations
// is limited. For a snake of length 6 on a grid, the number of self-avoiding walks of length 5
// is at most 4 * 3^4 = 324. So the total states are at most 2500 * 324 ≈ 810,000, which is fine.

// We'll precompute all possible body shapes (relative positions from head) that are valid.
// Then BFS from the initial state to the first food, then from that state to the next, etc.

// Actually, we don't need to precompute all shapes; we can just BFS directly with a visited array
// that maps (head_x, head_y, body_direction_code) to visited. The body direction code can be
// computed from the positions of the body segments relative to head.

// Simpler: Since the grid is small, we can do BFS for each food step, and for each state we
// generate the next state by moving the head in 4 directions, and then the body follows.
// We'll use a hash set for visited states. The state is a tuple of 6 (x,y) pairs.
// We can encode it as a 64-bit integer: each coordinate is 6 bits (0-63), so 12 bits per segment,
// 6 segments = 72 bits, which fits in a 128-bit integer or two 64-bit integers.
// We'll use a simple approach: store the state as a string or array and use a hash table.

// Given the small constraints, we can also do a simple BFS for each food step without full state
// tracking by treating the body as obstacles that move, but we need to ensure we don't revisit
// the same state. A common trick for snake problems: BFS from head to food, but the body moves
// along the path. However, the body is not fixed; it follows the head's path.

// Alternative: Since the body is short (5 segments), we can do a BFS where we store the positions
// of all segments. The number of states is manageable.

// We'll implement a BFS that for each food step, explores from the current state until it reaches
// the food. We'll use a queue and a visited set (implemented as a hash table or just a 6D array?).
// 6D array of size 50^6 is impossible. So we need a hash.

// Given the small grid (max 50x50=2500) and short body, the number of states is at most
// 2500 * (number of body shapes). The number of body shapes for a snake of length 6 is
// the number of self-avoiding walks of length 5 starting from origin, which is at most 4*3^4=324.
// So total states ≤ 2500*324 = 810,000. We can store visited as a hash set of 64-bit integers.

// Let's encode state: head (x,y) and then for i=1..5, body[i] relative to head? Actually we need
// absolute positions because the body can be anywhere. But we can encode as:
// state_id = (head_x * W + head_y) * (max_shape_id) + shape_id
// where shape_id is an index into a list of possible body shapes relative to head.
// But generating all shapes is a bit complex.

// Another approach: Since the body follows the head's path, the body positions are determined by
// the last 5 positions of the head. So if we store the head's path (the last 5 moves), we can
// reconstruct the body. So the state is the head position and a sequence of 5 directions (or positions).
// The directions are from the previous head positions. This is like storing the tail of the path.

// Let's define state as: head position (x,y) and an array of 5 relative directions (dx,dy) that
// represent the positions of the body segments relative to the head? Actually, if we know the
// head position and the previous 5 head positions, we know the body. But the previous positions
// are not necessarily adjacent in a straight line; they are the actual path.

// Simpler: Store the positions of all 6 segments. Since the body is short, we can store them
// in an array and use a hash function.

// We'll implement a simple hash set using a linked list array.

#define MAX_STATES 1000000

typedef struct node {
    long long key;
    struct node *next;
} Node;

Node *hash_table[1000003];
Node nodes[MAX_STATES];
int node_cnt;

void hash_init() {
    memset(hash_table, 0, sizeof(hash_table));
    node_cnt = 0;
}

int hash_func(long long key) {
    return (int)((key * 2654435761LL) % 1000003);
}

void hash_insert(long long key) {
    int h = hash_func(key);
    nodes[node_cnt].key = key;
    nodes[node_cnt].next = hash_table[h];
    hash_table[h] = &nodes[node_cnt];
    node_cnt++;
}

int hash_find(long long key) {
    int h = hash_func(key);
    Node *cur = hash_table[h];
    while (cur) {
        if (cur->key == key) return 1;
        cur = cur->next;
    }
    return 0;
}

// Encode state: 6 points, each 0-49, so 6 bits each, total 36 bits per coordinate? Actually we need 6 bits for x and 6 for y, so 12 bits per segment, 6 segments = 72 bits.
// We'll use two 64-bit integers: low and high.
typedef struct {
    long long low, high;
} StateKey;

StateKey make_key(Point *body) {
    StateKey k;
    k.low = 0;
    k.high = 0;
    for (int i = 0; i < 6; i++) {
        long long val = (body[i].x * W + body[i].y);
        if (i < 4) {
            k.low |= (val << (i * 12));
        } else {
            k.high |= (val << ((i-4) * 12));
        }
    }
    return k;
}

// For hashing, we can combine low and high
long long combine_key(StateKey k) {
    return k.low ^ (k.high * 1000003);
}

int is_valid(int x, int y) {
    return x >= 0 && x < H && y >= 0 && y < W && grid[x][y] != '#';
}

int is_body(Point *body, int x, int y, int head_only) {
    // check if (x,y) is in body (excluding head if head_only)
    for (int i = head_only ? 1 : 0; i < 6; i++) {
        if (body[i].x == x && body[i].y == y) return 1;
    }
    return 0;
}

// BFS from current state to target food position
// Returns number of steps, or -1 if impossible.
// Updates the body to the final state (head at food, body follows path)
int bfs_to_food(Point *body, int target_x, int target_y) {
    // Queue for BFS: store state and distance
    // We'll use arrays for queue
    Point queue_body[1000000][6];
    int queue_dist[1000000];
    int front = 0, rear = 0;

    // Insert initial state
    for (int i = 0; i < 6; i++) {
        queue_body[rear][i] = body[i];
    }
    queue_dist[rear] = 0;
    rear++;

    hash_init();
    StateKey k = make_key(body);
    hash_insert(combine_key(k));

    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    while (front < rear) {
        Point *cur = queue_body[front];
        int dist = queue_dist[front];
        front++;

        // Check if head is at target
        if (cur[0].x == target_x && cur[0].y == target_y) {
            // Copy final state to body
            for (int i = 0; i < 6; i++) {
                body[i] = cur[i];
            }
            return dist;
        }

        // Try 4 directions
        for (int d = 0; d < 4; d++) {
            int nx = cur[0].x + dx[d];
            int ny = cur[0].y + dy[d];
            if (!is_valid(nx, ny)) continue;
            // Check if new head position is on body (excluding tail which will move)
            // The tail will move away, so we need to check if the new head collides with
            // any segment except the last one (which will become the new tail after moving)
            // Actually, when the head moves, the body shifts: each segment moves to the position
            // of the previous segment. So the tail (last segment) moves to the previous position
            // of segment 4. So the new head cannot be on any segment except possibly the tail
            // which will move away. But careful: if the snake is in a loop, the tail might not
            // free the cell. Standard snake movement: the head moves, and the tail moves to the
            // previous position of the second-to-last segment. So the cell that was the tail
            // becomes free. So the new head can occupy the position of the tail (since it moves).
            // But it cannot occupy any other body segment.
            // Check if new head is on body segments 0..4 (head to 4th segment) because segment 5
            // (tail) will move away.
            int collision = 0;
            for (int i = 0; i < 5; i++) { // check head (0) to segment 4
                if (cur[i].x == nx && cur[i].y == ny) {
                    collision = 1;
                    break;
                }
            }
            if (collision) continue;

            // New state: head moves to (nx,ny), then segments shift
            Point new_body[6];
            new_body[0].x = nx;
            new_body[0].y = ny;
            for (int i = 1; i < 6; i++) {
                new_body[i] = cur[i-1];
            }

            // Check if this state has been visited
            StateKey nk = make_key(new_body);
            long long ck = combine_key(nk);
            if (hash_find(ck)) continue;
            hash_insert(ck);

            // Enqueue
            for (int i = 0; i < 6; i++) {
                queue_body[rear][i] = new_body[i];
            }
            queue_dist[rear] = dist + 1;
            rear++;
        }
    }
    return -1;
}

int main() {
    // Read input
    scanf("%d %d", &H, &W);
    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
    }

    // Find initial caterpillar and food positions
    Point init_body[6];
    int found = 0;
    food_count = 0;
    memset(food_order, 0, sizeof(food_order));

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            char c = grid[i][j];
            if (c == 'S') {
                init_body[0].x = i;
                init_body[0].y = j;
            } else if (c >= 'a' && c <= 'e') {
                int idx = c - 'a' + 1;
                init_body[idx].x = i;
                init_body[idx].y = j;
            } else if (c >= '1' && c <= '9') {
                int num = c - '0';
                food_pos[num].x = i;
                food_pos[num].y = j;
                food_count++;
            }
        }
    }

    // Determine the order of food to eat (from '1' to highest)
    target_order = 0;
    for (int i = 1; i <= 9; i++) {
        if (food_pos[i].x != 0 || food_pos[i].y != 0) {
            // Actually we need to check if food exists; we used 0,0 as sentinel but (0,0) could be a valid position.
            // Better: initialize food_pos with -1.
        }
    }

    // Let's reinitialize food_pos properly
    for (int i = 0; i <= 9; i++) {
        food_pos[i].x = -1;
        food_pos[i].y = -1;
    }
    food_count = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            char c = grid[i][j];
            if (c >= '1' && c <= '9') {
                int num = c - '0';
                food_pos[num].x = i;
                food_pos[num].y = j;
                food_count++;
            }
        }
    }

    // Find the maximum food number that exists
    target_order = 0;
    for (int i = 1; i <= 9; i++) {
        if (food_pos[i].x != -1) {
            target_order = i;
        }
    }

    // Start from initial body
    Point current_body[6];
    for (int i = 0; i < 6; i++) {
        current_body[i] = init_body[i];
    }

    int total_steps = 0;
    for (int f = 1; f <= target_order; f++) {
        int steps = bfs_to_food(current_body, food_pos[f].x, food_pos[f].y);
        if (steps == -1) {
            printf("-1\n");
            return 0;
        }
        total_steps += steps;
    }

    printf("%d\n", total_steps);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 25
#define MAXCELLS 625
#define MAXFOOD 10

char grid[MAXN][MAXN];
int R, C;
int food_pos[MAXFOOD]; // position of food 1..9
int num_food;
int dx[]={-1,1,0,0};
int dy[]={0,0,-1,1};

// State: 6 positions (each 0..MAXCELLS-1) + food_idx
// Encode as 64-bit integer
#include <stdint.h>
typedef uint64_t State;

State encode(int pos[6], int fi){
    State s=fi;
    for(int i=0;i<6;i++) s = s*MAXCELLS + pos[i];
    return s;
}

#define HTSIZE (1<<23)
#define HTMASK (HTSIZE-1)
State ht[HTSIZE];
int ht_used[HTSIZE];
int gen=0;

int ht_has(State s){
    uint32_t h=(uint32_t)(s^(s>>32))&HTMASK;
    while(ht_used[h]==gen && ht[h]!=s){h=(h+1)&HTMASK;}
    if(ht_used[h]==gen && ht[h]==s) return 1;
    ht[h]=s; ht_used[h]=gen; return 0;
}

typedef struct{int pos[6];int fi;} Node;
Node *q1,*q2;
int q1s,q2s,q1cap,q2cap;

int main(){
    scanf("%d%d",&R,&C);
    for(int i=0;i<R;i++) scanf("%s",grid[i]);
    int init[6];
    num_food=0;
    char order[]="Sabcde";
    for(int i=0;i<R;i++) for(int j=0;j<C;j++){
        char ch=grid[i][j];
        for(int k=0;k<6;k++) if(ch==order[k]) init[k]=i*C+j;
        if(ch>='1'&&ch<='9'){if(ch-'0'>num_food)num_food=ch-'0'; food_pos[ch-'0']=i*C+j;}
    }
    gen++;
    int cap=1<<16; q1=malloc(cap*sizeof(Node)); q1cap=cap; q1s=0;
    cap=1<<16; q2=malloc(cap*sizeof(Node)); q2cap=cap; q2s=0;
    Node start; memcpy(start.pos,init,24); start.fi=1;
    if(num_food==0){printf("0\n");return 0;}
    State s0=encode(init,1); ht_has(s0);
    q1[q1s++]=start;
    for(int step=1;;step++){
        if(q1s==0){printf("-1\n");return 0;}
        q2s=0;
        for(int qi=0;qi<q1s;qi++){
            Node*nd=&q1[qi];
            int hp=nd->pos[0],fi=nd->fi;
            int hr=hp/C,hc=hp%C;
            for(int d=0;d<4;d++){
                int nr=hr+dx[d],nc=hc+dy[d];
                if(nr<0||nr>=R||nc<0||nc>=C) continue;
                if(grid[nr][nc]=='#') continue;
                int np=nr*C+nc;
                int collision=0;
                for(int k=0;k<5;k++) if(np==nd->pos[k+1]){collision=1;break;}
                if(collision) continue;
                int nfi=fi;
                if(np==food_pos[fi]) nfi=fi+1;
                if(nfi>num_food){printf("%d\n",step);return 0;}
                int npos[6]; npos[0]=np;
                for(int k=0;k<5;k++) npos[k+1]=nd->pos[k];
                State ns=encode(npos,nfi);
                if(!ht_has(ns)){
                    if(q2s>=q2cap){q2cap*=2;q2=realloc(q2,q2cap*sizeof(Node));}
                    Node nn; memcpy(nn.pos,npos,24); nn.fi=nfi;
                    q2[q2s++]=nn;
                }
            }
        }
        Node*tmp=q1;q1=q2;q2=tmp;int t=q1cap;q1cap=q2cap;q2cap=t;q1s=q2s;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXH 16
#define MAXW 16
#define MAXN 256
#define INF 1000000000

typedef struct {
    int hx, hy;
    unsigned int code; /* 5 body segment directions from predecessor, base-4 */
} State;

typedef struct {
    int x, y;
} Pos;

static int H, W, N;
static char grid[MAXH][MAXW + 1];
static Pos foods[10];
static int foodCount;

static int dx[4] = {-1, 1, 0, 0};
static int dy[4] = {0, 0, -1, 1};

static int q[MAXN * MAXN * 1024];
static int dista[MAXN * MAXN * 1024];

static int in_bounds(int x, int y) {
    return (0 <= x && x < H && 0 <= y && y < W);
}

static int encode_state(int hx, int hy, unsigned int code) {
    return ((hx * W + hy) << 10) | code; /* 4^5 = 1024 */
}

static void decode_dirs(unsigned int code, int dirs[5]) {
    for (int i = 0; i < 5; i++) {
        dirs[i] = code & 3u;
        code >>= 2;
    }
}

/* reconstruct positions:
   pos[0] = head, pos[1] = a, ..., pos[5] = e
   dirs[i] means direction from pos[i] to pos[i+1]
*/
static void reconstruct(int hx, int hy, unsigned int code, int px[6], int py[6]) {
    int dirs[5];
    decode_dirs(code, dirs);
    px[0] = hx; py[0] = hy;
    for (int i = 0; i < 5; i++) {
        px[i + 1] = px[i] + dx[dirs[i]];
        py[i + 1] = py[i] + dy[dirs[i]];
    }
}

static unsigned int next_code_from_positions(int nx, int ny, int px[6], int py[6]) {
    /* new snake after moving head to (nx,ny):
       new pos[0]=(nx,ny), new pos[1]=old head, ..., new pos[5]=old pos[4]
       encode directions from new pos[i] to new pos[i+1]
    */
    int sx[6], sy[6];
    sx[0] = nx; sy[0] = ny;
    for (int i = 1; i < 6; i++) {
        sx[i] = px[i - 1];
        sy[i] = py[i - 1];
    }

    unsigned int code = 0;
    for (int i = 4; i >= 0; i--) {
        int dd = -1;
        for (int d = 0; d < 4; d++) {
            if (sx[i] + dx[d] == sx[i + 1] && sy[i] + dy[d] == sy[i + 1]) {
                dd = d;
                break;
            }
        }
        code = (code << 2) | (unsigned int)dd;
    }
    return code;
}

static int bfs(State start, int tx, int ty) {
    int totalStates = H * W * 1024;
    for (int i = 0; i < totalStates; i++) dista[i] = -1;

    int head = 0, tail = 0;
    int sid = encode_state(start.hx, start.hy, start.code);
    q[tail++] = sid;
    dista[sid] = 0;

    while (head < tail) {
        int id = q[head++];
        unsigned int code = (unsigned int)(id & 1023);
        int cell = id >> 10;
        int hx = cell / W;
        int hy = cell % W;
        int cd = dista[id];

        if (hx == tx && hy == ty) {
            start.hx = hx;
            start.hy = hy;
            start.code = code;
            return id;
        }

        int px[6], py[6];
        reconstruct(hx, hy, code, px, py);

        for (int d = 0; d < 4; d++) {
            int nx = hx + dx[d];
            int ny = hy + dy[d];
            if (!in_bounds(nx, ny)) continue;
            if (grid[nx][ny] == '#') continue;

            int bad = 0;
            /* cannot move into body except current tail cell (which moves away) */
            for (int i = 0; i < 5; i++) { /* positions 1..5 ; tail is 5 */
                if (nx == px[i + 1] && ny == py[i + 1]) {
                    if (i + 1 != 5) bad = 1;
                }
            }
            if (bad) continue;

            unsigned int ncode = next_code_from_positions(nx, ny, px, py);
            int nid = encode_state(nx, ny, ncode);
            if (dista[nid] == -1) {
                dista[nid] = cd + 1;
                q[tail++] = nid;
            }
        }
    }
    return -1;
}

int main(void) {
    if (scanf("%d %d %d", &H, &W, &N) != 3) return 0;
    for (int i = 0; i < H; i++) scanf("%s", grid[i]);

    Pos seg[6];
    foodCount = N;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            char c = grid[i][j];
            if (c == 'S') seg[0].x = i, seg[0].y = j;
            else if (c >= 'a' && c <= 'e') {
                int idx = c - 'a' + 1;
                seg[idx].x = i;
                seg[idx].y = j;
            } else if (c >= '1' && c <= '9') {
                foods[c - '1'].x = i;
                foods[c - '1'].y = j;
            }
        }
    }

    unsigned int initCode = 0;
    for (int i = 4; i >= 0; i--) {
        int dd = -1;
        for (int d = 0; d < 4; d++) {
            if (seg[i].x + dx[d] == seg[i + 1].x && seg[i].y + dy[d] == seg[i + 1].y) {
                dd = d;
                break;
            }
        }
        initCode = (initCode << 2) | (unsigned int)dd;
    }

    State cur;
    cur.hx = seg[0].x;
    cur.hy = seg[0].y;
    cur.code = initCode;

    int answer = 0;

    for (int k = 0; k < N; k++) {
        int targetX = foods[k].x;
        int targetY = foods[k].y;

        int endId = bfs(cur, targetX, targetY);
        if (endId == -1) {
            printf("-1\n");
            return 0;
        }

        answer += dista[endId];
        cur.hx = (endId >> 10) / W;
        cur.hy = (endId >> 10) % W;
        cur.code = (unsigned int)(endId & 1023);
    }

    printf("%d\n", answer);
    return 0;
}

import java.util.*;

public class Main {
    static int R, C;
    static char[][] grid;
    static int[] dr = {-1,1,0,0};
    static int[] dc = {0,0,-1,1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        R = sc.nextInt(); C = sc.nextInt();
        grid = new char[R][C];
        int[] seg = new int[6]; // positions as r*C+c
        int maxFood = 0;
        for(int i=0;i<R;i++){
            String line = sc.next();
            for(int j=0;j<C;j++){
                grid[i][j]=line.charAt(j);
                char ch=grid[i][j];
                if(ch=='S') seg[0]=i*C+j;
                else if(ch=='a') seg[1]=i*C+j;
                else if(ch=='b') seg[2]=i*C+j;
                else if(ch=='c') seg[3]=i*C+j;
                else if(ch=='d') seg[4]=i*C+j;
                else if(ch=='e') seg[5]=i*C+j;
                if(ch>='1'&&ch<='9') maxFood=Math.max(maxFood,ch-'0');
            }
        }
        // compute initial directions
        int[] dirs = new int[5];
        for(int i=0;i<5;i++){
            int dr2=seg[i]/C-seg[i+1]/C, dc2=seg[i]%C-seg[i+1]%C;
            for(int d=0;d<4;d++) if(dr[d]==dr2&&dc[d]==dc2){dirs[i]=d;break;}
        }
        int N=R*C, F=maxFood+1;
        // state: head*1024*F + dirsEnc*F + nextFood
        Map<Long,Integer> dist=new HashMap<>();
        Queue<long[]> queue=new LinkedList<>();
        long initState=encode(seg[0],dirs,0,F);
        dist.put(initState,0);
        queue.add(new long[]{initState,0});
        while(!queue.isEmpty()){
            long[] cur=queue.poll();
            long state=cur[0]; int steps=(int)cur[1];
            if(dist.get(state)!=steps) continue;
            int[] info=decode(state,F);
            int head=info[0]; int[] d2=new int[]{info[1],info[2],info[3],info[4],info[5]}; int nf=info[6];
            if(nf==maxFood+1){System.out.println(steps);return;}
            // rebuild positions
            int[] pos=new int[6]; pos[0]=head;
            for(int i=0;i<5;i++){int r=pos[i]/C-dr[d2[i]],c=pos[i]%C-dc[d2[i]];pos[i+1]=r*C+c;}
            for(int mv=0;mv<4;mv++){
                int nr=head/C+dr[mv],nc=head%C+dc[mv];
                if(nr<0||nr>=R||nc<0||nc>=C) continue;
                if(grid[nr][nc]=='#') continue;
                int np=nr*C+nc;
                boolean body=false; for(int i=0;i<5;i++) if(pos[i+1]==np){body=true;break;}
                if(body) continue;
                int nnf=nf; char ch=grid[nr][nc];
                if(ch>='1'&&ch<='9'&&(ch-'0')==nf+1) nnf=nf+1;
                else if(ch>='1'&&ch<='9'&&(ch-'0')<=nf) {} // ok pass over eaten food? 
                // actually food cells remain, caterpillar can pass over them
                int[] nd={mv,d2[0],d2[1],d2[2],d2[3]};
                long ns=encode(np,nd,nnf,F);
                if(!dist.containsKey(ns)||dist.get(ns)>steps+1){
                    dist.put(ns,steps+1); queue.add(new long[]{ns,steps+1});}
            }
        }
        System.out.println(-1);
    }
    static long encode(int head,int[]dirs,int nf,int F){
        long d=0; for(int i=0;i<5;i++) d=d*4+dirs[i];
        return (head*1024L+d)*F+nf;
    }
    static int[] decode(long state,int F){
        int nf=(int)(state%F); state/=F;
        int d=(int)(state%1024); state/=1024;
        int head=(int)state;
        int[]dirs=new int[5]; for(int i=4;i>=0;i--){dirs[i]=d%4;d/=4;}
        return new int[]{head,dirs[0],dirs[1],dirs[2],dirs[3],dirs[4],nf};
    }
}

