        int[] foodY = new int[foodCount];
        for (int i = 0; i < foodCount; i++) {
            foodX[i] = foodPositions.get(i)[0];
            foodY[i] = foodPositions.get(i)[1];
        }

        // For DP, we need to compute distances between states. We'll do BFS for each transition on the fly.
        // We'll store dp[mask][last] as min steps, but we also need the body configuration after eating last food to compute next distance.
