        int[] initDirs = new int[5];
        for (int i = 0; i < 5; i++) {
            int[] from = initBody.get(i);
            int[] to = initBody.get(i+1);
            int dx = to[0] - from[0];
            int dy = to[1] - from[1];
            if (dx == 0 && dy == 1) initDirs[i] = 0; // right
            else if (dx == 0 && dy == -1) initDirs[i] = 1; // left
