        startList.add(new State(startHead[0], startHead[1], initDirHist, 0));
        dpMap.put(key0, startList);

        int fullMask = (1 << foodCount) - 1;
        int answer = Integer.MAX_VALUE;

        // Process masks in increasing order
        for (int mask = 0; mask < (1 << foodCount); mask++) {
            for (int last = -1; last < foodCount; last++) {
                if (last != -1 && ((mask >> last) & 1) == 0) continue;
