                        int[] res = bfsToFood(s.hx, s.hy, s.dirHist, targetX, targetY);
                        if (res == null) continue;
                        int newSteps = s.steps + res[0];
                        int newDirHist = res[1];
                        int newHx = targetX;
                        int newHy = targetY;
                        int newMask = mask | (1 << next);
                        long newKey = encodeKey(newMask, next);
                        List<State> newList = dpMap.get(newKey);
                        if (newList == null) {
                            newList = new ArrayList<>();
                            dpMap.put(newKey, newList);
                        }
                        // Check if we already have a state with same head and dirHist but lower steps
                        boolean add = true;
                        Iterator<State> it = newList.iterator();
                        while (it.hasNext()) {
                            State old = it.next();
                            if (old.hx == newHx && old.hy == newHy && old.dirHist == newDirHist) {
                                if (old.steps <= newSteps) {
                                    add = false;
                                    break;
                                } else {
                                    it.remove();
                                }
                            }
                        }
                        if (add) {
                            newList.add(new State(newHx, newHy, newDirHist, newSteps));
                        }
                    }
                }
            }
        }

        System.out.println(answer == Integer.MAX_VALUE ? -1 : answer);
    }

    static long encodeKey(int mask, int last) {
        return ((long)mask << 32) | (last + 1); // last+1 to handle -1
    }

    // BFS from (hx, hy, dirHist) to (tx, ty). Returns [steps, newDirHist] or null if impossible.
    static int[] bfsToFood(int shx, int shy, int sdirHist, int tx, int ty) {
        // State: headX, headY, dirHist (int)
        // We'll BFS using queue and visited set encoded as long: (headX << 20) | (headY << 10) | dirHist (10 bits for dirHist? 4^5=1024 need 10 bits)
        // headX up to 49 (6 bits), headY up to 49 (6 bits), dirHist up to 1023 (10 bits) => total 22 bits, fits in int.
        int startEnc = encodeState(shx, shy, sdirHist);
        Queue<Integer> q = new LinkedList<>();
        Map<Integer, Integer> dist = new HashMap<>();
        Map<Integer, Integer> prevDirHist = new HashMap<>(); // not needed
        q.add(startEnc);
        dist.put(startEnc, 0);
        while (!q.isEmpty()) {
            int curEnc = q.poll();
            int curDist = dist.get(curEnc);
            int hx = (curEnc >> 16) & 0x3F;
            int hy = (curEnc >> 10) & 0x3F;
            int dirHist = curEnc & 0x3FF;

            // Check if head at target
            if (hx == tx && hy == ty) {
                return new int[]{curDist, dirHist};
            }

            // Try 4 directions
            for (int d = 0; d < 4; d++) {
                int nx = hx + dx[d];
                int ny = hy + dy[d];
                if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
                if (grid[nx][ny] == '#') continue;
                // Compute body positions from current dirHist
                // Body: head at (hx, hy), then 5 segments following dirHist in reverse
                // We need to check if (nx, ny) is occupied by any body segment (except head)
                boolean collision = false;
                int curX = hx, curY = hy;
                int hist = dirHist;
                for (int i = 0; i < 5; i++) {
                    int dir = hist & 3;
                    hist >>= 2;
                    curX -= dx[dir];
                    curY -= dy[dir];
                    if (curX == nx && curY == ny) {
                        collision = true;
                        break;
                    }
                }
                if (collision) continue;

                // New direction history: shift left and add new direction
                int newDirHist = ((dirHist << 2) | d) & 0x3FF; // keep only 10 bits (5 directions * 2 bits)
                int newEnc = encodeState(nx, ny, newDirHist);
                if (!dist.containsKey(newEnc)) {
                    dist.put(newEnc, curDist + 1);
                    q.add(newEnc);
                }
            }
        }
        return null;
    }

    static int encodeState(int hx, int hy, int dirHist) {
        return (hx << 16) | (hy << 10) | dirHist;
    }
