import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class State {
        int[] pos; // pos[0]=head, pos[1..5]=body
        int food;  // already eaten count
        int dist;

        State(int[] pos, int food, int dist) {
            this.pos = pos;
            this.food = food;
            this.dist = dist;
        }
    }

    static int H, W;
    static char[][] grid;
    static int totalFood;
    static int[] foodPos = new int[10]; // 1..9
    static final int[] dr = {-1, 1, 0, 0};
    static final int[] dc = {0, 0, -1, 1};

    static int encodeState(int[] pos, int food, int cells) {
        int key = food;
        for (int i = 0; i < 6; i++) {
            key = key * cells + pos[i];
        }
        return key;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        H = fs.nextInt();
        W = fs.nextInt();
        grid = new char[H][W];

        int[] initial = new int[6];
        Arrays.fill(initial, -1);

        for (int r = 0; r < H; r++) {
            String s = fs.next();
            for (int c = 0; c < W; c++) {
                char ch = s.charAt(c);
                grid[r][c] = ch;
                if (ch == 'S') initial[0] = r * W + c;
                else if (ch >= 'a' && ch <= 'e') initial[ch - 'a' + 1] = r * W + c;
                else if (ch >= '1' && ch <= '9') {
                    int idx = ch - '0';
                    foodPos[idx] = r * W + c;
                    totalFood = Math.max(totalFood, idx);
                }
            }
        }

        int ans = bfs(initial);
        System.out.println(ans);
    }

    static int bfs(int[] startPos) {
        int cells = H * W;
        ArrayDeque<State> q = new ArrayDeque<>();
        HashSet<Integer> visited = new HashSet<>();

        int startKey = encodeState(startPos, 0, cells);
        visited.add(startKey);
        q.add(new State(startPos, 0, 0));

        while (!q.isEmpty()) {
            State cur = q.poll();
            if (cur.food == totalFood) return cur.dist;

            int head = cur.pos[0];
            int hr = head / W, hc = head % W;

            for (int d = 0; d < 4; d++) {
                int nr = hr + dr[d];
                int nc = hc + dc[d];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                if (grid[nr][nc] == '#') continue;

                int np = nr * W + nc;

                // cannot move into current body except tail (which moves away)
                boolean bad = false;
                for (int i = 1; i <= 4; i++) {
                    if (cur.pos[i] == np) {
                        bad = true;
                        break;
                    }
                }
                if (bad) continue;

                int[] nextPos = new int[6];
                nextPos[0] = np;
                for (int i = 1; i < 6; i++) nextPos[i] = cur.pos[i - 1];

                int nextFood = cur.food;
                if (cur.food < totalFood && np == foodPos[cur.food + 1]) {
                    nextFood++;
                }

                int key = encodeState(nextPos, nextFood, cells);
                if (visited.add(key)) {
                    q.add(new State(nextPos, nextFood, cur.dist + 1));
                }
            }
        }
        return -1;
    }
}
